-- HANA-SOURCE: cl/bcs/tesoreria/sql/AnularNominasTransferencias_UpdateLiberarFormaDePagoMovimientosOriginales.sql
-- H2 rewrite (join chain IEFP-IE-CDO-CD-COM-CFP-NT-RP -> EXISTS over IE/CDO ...).
UPDATE "BSCL.Tesoreria.BD::TES.IngresoEgresoFormaDePago" AS IEFP SET "IdEstado" = 'ING' WHERE IEFP."IdEstado" NOT IN ('ANU', 'MOD') AND EXISTS (SELECT 1 FROM "BSCL.Tesoreria.BD::TES.IngresoEgreso" AS IE INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteDetalleOrigen" AS CDO ON IE."IdIngresoEgreso" = CDO."IdIngresoEgreso" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteDetalle" AS CD ON CDO."IdComprobanteDetalle" = CD."IdComprobanteDetalle" INNER JOIN "BSCL.Tesoreria.BD::TES.Comprobante" AS COM ON CD."IdComprobante" = COM."IdComprobante" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON COM."IdComprobante" = CFP."IdComprobante" INNER JOIN "BSCL.Tesoreria.BD::TES.NominaTransferencia" AS NT ON CFP."IdComprobantePartida" = NT."IdComprobantePartidaEgreso" INNER JOIN TT_AnularNominasTransferencias_p_RegistrosAProcesar AS RP ON RP."Id" = NT."IdNominaTransferencia" WHERE IEFP."IdIngresoEgreso" = IE."IdIngresoEgreso")
